#include <stdlib.h>
#include <string.h>
#include <omp.h>

#if defined(__AVX512F__)
#define W 16
#define MR 12
#elif defined(__AVX__)
#define W 8
#define MR 6
#else
#define W 4
#define MR 6
#endif

#define NR (2 * W)
#define KCMAX 384
#define MC (MR * 8)
#define NCOLS 256
#define NCP (NCOLS / NR)

typedef float V __attribute__((vector_size(W * 4), may_alias));
typedef float VU __attribute__((vector_size(W * 4), aligned(4), may_alias));

#if MR == 12
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5) X(6) X(7) X(8) X(9) X(10) X(11)
#else
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5)
#endif

static inline __attribute__((always_inline))
void kern(const float *restrict a, long lda, const float *restrict b, int kc,
          float *restrict c, long ldc, int first)
{
#define DECL(r) V c##r##0 = {0}, c##r##1 = {0};
    ROWS(DECL)
    const long l2 = 2 * lda;
    const float *a0 = a, *a3 = a + 3 * lda;
#if MR == 12
    const float *a6 = a + 6 * lda, *a9 = a + 9 * lda;
#endif
    for (int p = 0; p < kc; p++) {
        V b0 = *(const V *)b;
        V b1 = *(const V *)(b + W);
        b += NR;
#define FMA(r, ptr, off) { float s = ptr[off]; c##r##0 += b0 * s; c##r##1 += b1 * s; }
        FMA(0, a0, 0) FMA(1, a0, lda) FMA(2, a0, l2)
        FMA(3, a3, 0) FMA(4, a3, lda) FMA(5, a3, l2)
#if MR == 12
        FMA(6, a6, 0) FMA(7, a6, lda) FMA(8, a6, l2)
        FMA(9, a9, 0) FMA(10, a9, lda) FMA(11, a9, l2)
        a6++; a9++;
#endif
        a0++; a3++;
    }
#define STORE(r) { VU *p0 = (VU *)(c + (r) * ldc), *p1 = (VU *)(c + (r) * ldc + W); \
        if (first) { *p0 = c##r##0; *p1 = c##r##1; } else { *p0 += c##r##0; *p1 += c##r##1; } }
    ROWS(STORE)
}

static float *bbuf = NULL;
static size_t bcap = 0;

void matmul(const float *A, const float *B, float *C, int n)
{
    const int np = (n + NR - 1) / NR;          /* column panels */
    const long npad = (long)np * NR;
    const int nkb = (n + KCMAX - 1) / KCMAX;
    const int kcb = (n + nkb - 1) / nkb;

    size_t need = ((size_t)npad * n * sizeof(float) + 63) & ~(size_t)63;
    if (need > bcap) {
        free(bbuf);
        bbuf = aligned_alloc(64, need);
        bcap = need;
    }
    float *Bp = bbuf;

    const int nrt = (n + MC - 1) / MC;         /* row tasks */
    const int nct = (np + NCP - 1) / NCP;      /* column tasks */
    const int ntasks = nrt * nct;
    const int npanels = nkb * np;

    #pragma omp parallel if (n >= 96)
    {
        #pragma omp for schedule(static)
        for (int t = 0; t < npanels; t++) {
            int kb = t / np, jp = t % np;
            int k0 = kb * kcb, kc = n - k0 < kcb ? n - k0 : kcb;
            int j = jp * NR, nr = n - j < NR ? n - j : NR;
            float *dst = Bp + (long)k0 * npad + (long)jp * NR * kc;
            const float *src = B + (long)k0 * n + j;
            if (nr == NR) {
                for (int p = 0; p < kc; p++)
                    memcpy(dst + (long)p * NR, src + (long)p * n, NR * sizeof(float));
            } else {
                for (int p = 0; p < kc; p++) {
                    int jj = 0;
                    for (; jj < nr; jj++) dst[(long)p * NR + jj] = src[(long)p * n + jj];
                    for (; jj < NR; jj++) dst[(long)p * NR + jj] = 0.0f;
                }
            }
        }

        float ebuf[MR * KCMAX] __attribute__((aligned(64)));
        float ct[MR * NR] __attribute__((aligned(64)));

        #pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < ntasks; t++) {
            int i0 = (t / nct) * MC, i1 = i0 + MC < n ? i0 + MC : n;
            int jp0 = (t % nct) * NCP, jp1 = jp0 + NCP < np ? jp0 + NCP : np;
            for (int kb = 0; kb < nkb; kb++) {
                int k0 = kb * kcb, kc = n - k0 < kcb ? n - k0 : kcb;
                const float *bs = Bp + (long)k0 * npad;
                int first = (kb == 0);
                for (int i = i0; i < i1; i += MR) {
                    int mr = n - i < MR ? n - i : MR;
                    const float *ap;
                    long lda;
                    if (mr == MR) {
                        ap = A + (long)i * n + k0;
                        lda = n;
                    } else {
                        for (int r = 0; r < MR; r++) {
                            if (r < mr)
                                memcpy(ebuf + r * kc, A + (long)(i + r) * n + k0, kc * sizeof(float));
                            else
                                memset(ebuf + r * kc, 0, kc * sizeof(float));
                        }
                        ap = ebuf;
                        lda = kc;
                    }
                    for (int jp = jp0; jp < jp1; jp++) {
                        int j = jp * NR, nr = n - j < NR ? n - j : NR;
                        const float *bp = bs + (long)jp * NR * kc;
                        float *cp = C + (long)i * n + j;
                        if (mr == MR && nr == NR) {
                            kern(ap, lda, bp, kc, cp, n, first);
                        } else {
                            kern(ap, lda, bp, kc, ct, NR, 1);
                            for (int r = 0; r < mr; r++) {
                                float *cr = cp + (long)r * n;
                                const float *tr = ct + r * NR;
                                if (first)
                                    for (int jj = 0; jj < nr; jj++) cr[jj] = tr[jj];
                                else
                                    for (int jj = 0; jj < nr; jj++) cr[jj] += tr[jj];
                            }
                        }
                    }
                }
            }
        }
    }
}
